  # OwnershipRequestDeclaration is a request body of KUAA's API.
  class OwnershipRequestDeclaration < Params
    MEMBERS = %i[basis document_id from_party_id relationship_id share_percent to_party_id].freeze

    # What the share rests on. Empty is declaration.
    # @return [String ("declaration", "document", "reviewer"), nil]
    attr_reader :basis

    # The document of the case the share was read from, when the basis is a document.
    # @return [String, nil]
    attr_reader :document_id

    # The shareholder, a party of the case. With to_party_id, names the shareholder relationship, which is created when it does not exist.
    # @return [String, nil]
    attr_reader :from_party_id

    # The existing relationship the share is declared on. Give this, or both from_party_id and to_party_id.
    # @return [String, nil]
    attr_reader :relationship_id

    # The share held, more than 0 and at most 100.
    # @return [Float]
    attr_reader :share_percent

    # The company the share is held in, a party of the case; not from_party_id itself.
    # @return [String, nil]
    attr_reader :to_party_id

    def initialize(basis: nil, document_id: nil, from_party_id: nil, relationship_id: nil, share_percent:, to_party_id: nil)
      @basis = basis
      @document_id = document_id
      @from_party_id = from_party_id
      @relationship_id = relationship_id
      @share_percent = share_percent
      @to_party_id = to_party_id
      freeze
    end

    # The body as the API reads it.
    def to_wire
      wire = {}
      wire["basis"] = @basis unless @basis.nil?
      wire["document_id"] = @document_id unless @document_id.nil?
      wire["from_party_id"] = @from_party_id unless @from_party_id.nil?
      wire["relationship_id"] = @relationship_id unless @relationship_id.nil?
      wire["share_percent"] = @share_percent
      wire["to_party_id"] = @to_party_id unless @to_party_id.nil?
      wire
    end
  end

  # PersonLookupRequest is a request body of KUAA's API.
  class PersonLookupRequest < Params
    MEMBERS = %i[cpf include purpose].freeze

    # The CPF, as text, with or without punctuation; its check digits are verified before anything is asked.
    # @return [String]
    attr_reader :cpf

    # aml also asks AML Vínculos: PEP, and óbito with its date. Absent asks Cadastro PF Plus alone.
    # @return [Array<String ("aml")>, nil]
    attr_reader :include

    # Why the lookup is made (LGPD art. 6, I), recorded with it with its legal basis: onboarding (art. 7, V), fraud_prevention (art. 11, II, g), legal_obligation (art. 7, II), credit_protection (art. 7, X), contract_execution (art. 7, V).
    # @return [String ("onboarding", "fraud_prevention", "legal_obligation", "credit_protection", "contract_execution")]
    attr_reader :purpose

    def initialize(cpf:, include: nil, purpose:)
      @cpf = cpf
      @include = include
      @purpose = purpose
      freeze
    end

    # The body as the API reads it.
    def to_wire
      wire = {}
      wire["cpf"] = @cpf
      wire["include"] = Kuaa.wire(@include) unless @include.nil?
      wire["purpose"] = @purpose
      wire
    end
  end

